<script setup lang="ts">
import type { components } from '~/api/schema'; import { unwrap,versionHeaders } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatRupiah,lowestPrice } from '~/utils/format';
type Product=components['schemas']['Product'];definePageMeta({middleware:'auth'});const api=useMarketplaceApi();const portal=usePortal();const products=ref<Product[]>([]);const pending=ref(true);const error=ref<unknown>();const filter=ref('ALL');const q=ref('');
const visible=computed(()=>products.value.filter(p=>(filter.value==='ALL'||p.status===filter.value)&&(!q.value||p.name.toLowerCase().includes(q.value.toLowerCase()))));
async function load(){pending.value=true;error.value=undefined;try{if(!portal.activeStore.value)await portal.loadStores();if(!portal.storeId.value)return;products.value=unwrap(await api.GET('/vendor/stores/{storeId}/products',{params:{path:{storeId:portal.storeId.value},query:{limit:100}},cache:'no-store'})).items;}catch(cause){error.value=cause;}finally{pending.value=false;}}
async function transition(product:Product,action:'publish'|'archive'){try{unwrap(await api.POST(action==='publish'?'/vendor/stores/{storeId}/products/{productId}/publish':'/vendor/stores/{storeId}/products/{productId}/archive',{params:{path:{storeId:portal.storeId.value,productId:product.id},header:{...versionHeaders(product.row_version),'Idempotency-Key':crypto.randomUUID()}}} as any));await load();}catch(cause){error.value=cause;}}
watch(()=>portal.storeId.value,()=>{void load();});onMounted(()=>{void load();});useSeoMeta({title:'Produk vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Katalog toko</p><h1>Produk</h1></div><div class="form-actions"><StoreSwitcher/><NuxtLink class="button" to="/vendor/produk/baru">Tambah produk</NuxtLink></div></div><div class="filter-bar"><input v-model.trim="q" placeholder="Cari produk"><select v-model="filter"><option value="ALL">Semua status</option><option value="DRAFT">Draft</option><option value="ACTIVE">Aktif</option><option value="ARCHIVED">Diarsipkan</option></select></div><ApiState :pending="pending" :error="error?displayError(error):null" :empty="!pending&&!visible.length" empty-title="Produk tidak ditemukan" @retry="load"><div class="admin-table-wrap"><table><thead><tr><th>Produk</th><th>Status</th><th>SKU</th><th>Harga terendah</th><th>Aksi</th></tr></thead><tbody><tr v-for="product in visible" :key="product.id"><td><strong>{{ product.name }}</strong><small>{{ product.slug }}</small></td><td><span class="badge">{{ product.status }}</span></td><td>{{ product.skus.length }}</td><td>{{ lowestPrice(product)===null?'—':formatRupiah(lowestPrice(product)!) }}</td><td><div class="table-actions"><NuxtLink :to="`/vendor/produk/${product.id}`">Edit</NuxtLink><button v-if="product.status==='DRAFT'" class="text-button" @click="transition(product,'publish')">Publikasikan</button><button v-if="product.status!=='ARCHIVED'" class="text-button" @click="transition(product,'archive')">Arsipkan</button></div></td></tr></tbody></table></div></ApiState></main></template>
